def write(path: Path, rows: list[dict]) -> None:
    rows.sort(key=lambda r: r["ts"])
    with path.open("w", newline="") as fh:
        writer = csv.DictWriter(fh, fieldnames=["entity_id", "ts", "state"])
        writer.writeheader()
        writer.writerows(rows)
    print(f"wrote {len(rows)} rows to {path}")


def as_rows(
    date: str, samples: list[tuple[str, str]], shift_h: int = 0, shift_m: int = 0
) -> list[dict]:
    out = []
    for clock, value in samples:
        hh, mm, rest = clock.split(":", 2)
        minutes = int(hh) * 60 + int(mm) + shift_h * 60 + shift_m
        stamp = f"{minutes // 60:02d}:{minutes % 60:02d}:{rest}"
        out.append({"entity_id": WEIGHT, "ts": f"{date}T{stamp}+03:00", "state": value})
    return out


def main() -> None:
    here = Path(__file__).parent

    # Real recorder data, untouched.  Contains no dose->pour pair inside the 30 min
    # window: episode B's beans were never followed by a captured pour, and episode
    # C's pour is a day later.  So this fixture exercises detection, not pairing.
    real = []
    for date, samples in (EPISODE_A, EPISODE_B, EPISODE_C):
        real += as_rows(date, samples)
    write(here / "known_events.csv", real)

    # Same real waveforms, re-timed into one brew cycle so the pairing path is
    # exercised: beans at 19:42 (episode B) then the pour (episode A, shifted from
    # 18:48 to 19:53).  The shift must clear episode B's own last row at 19:48:45,
    # or that row lands inside the pour and cuts it in half.
    paired = as_rows("2026-08-09", EPISODE_B[1]) + as_rows(
        "2026-08-09", EPISODE_A[1], shift_h=1, shift_m=5
    )
    write(here / "synthetic_pair.csv", paired)

    # A real, complete brew cycle that the detector originally lost entirely.
    write(here / "lost_shot.csv", as_rows(*EPISODE_D))

    # Not coffee at all — the two-step weighings that exposed the plateau/weighing
    # confusion.  Must yield 30.0 g and 111.3 g, and must not report a brew.
    write(here / "porridge.csv", as_rows(*EPISODE_E))

    # The pour that settled twice and made the two sensors disagree.
    write(here / "settling.csv", as_rows(*EPISODE_F))

    # The cup lifted the moment the pour stopped — a whole cycle reported as nothing.
    write(here / "snatched.csv", as_rows(*EPISODE_G))

    # An empty cup tared to zero, which used to read as a 64 g pour.
    write(here / "tare.csv", as_rows(*EPISODE_H))

    # The same tare against a dead-still cup, which the first tare rule missed.
    write(here / "tare_still.csv", as_rows(*EPISODE_I))

    # Two dose candidates one after the other, separated only by how they arrived.
    write(here / "two_doses.csv", as_rows(*EPISODE_J))


if __name__ == "__main__":
    main()
